public record User(String id, Profile profile) {}
public record Profile(Address address) {}
public record Address(String zipCode) {}

public class UserService {
    public Optional<User> findUser(String id) {
        // Simulated lookup returning an Optional
        return Optional.ofNullable(databaseLookup(id));
    }

    public Optional<String> getZipCodeForUser(String userId) {
        return findUser(userId)
            .flatMap(User::profile)
            .flatMap(Profile::address)
            .map(Address::zipCode);
    }

    private User databaseLookup(String id) {
        return "123".equals(id) ? new User("123", new Profile(new Address("94107"))) : null;
    }
}
